import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.BZKbe9n2.js";const m=JSON.parse('{"title":"API für Quellen","description":"","frontmatter":{},"headers":[],"relativePath":"de/source-api/index.md","filePath":"de/source-api/index.md"}'),l={name:"de/source-api/index.md"};function d(s,e,a,o,u,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="api-fur-quellen" tabindex="-1">API für Quellen <a class="header-anchor" href="#api-fur-quellen" aria-label="Permalink to &quot;API für Quellen&quot;">​</a></h1><p>Anthology nimmt Musik aus anderen Quellen über <strong>Quelldienste</strong> auf: eigenständige Container, die je eine Quelle umhüllen und eine kleine HTTP/JSON-Schnittstelle sprechen. Der Kern enthält nie Download-Code für kommerzielle Dienste; ein Quelldienst kann eine eigene Lizenz und einen eigenen Release-Zyklus haben.</p><p>Dieser Teil richtet sich an Entwicklerinnen und Entwickler, die einen Quelldienst schreiben wollen.</p><h2 id="wie-es-zusammenspielt" tabindex="-1">Wie es zusammenspielt <a class="header-anchor" href="#wie-es-zusammenspielt" aria-label="Permalink to &quot;Wie es zusammenspielt&quot;">​</a></h2><ol><li>Der Server liest die Dienste aus <code>ANTHOLOGY_SOURCE_SERVICES</code> und prüft jeden jede Minute (<code>GET /v1/info</code>, <code>GET /v1/health</code>).</li><li>Benutzer durchsuchen einen Dienst oder fügen einen Link ein; der Server reicht die Anfrage weiter (<code>/v1/search</code>, <code>/v1/resolve</code>) und zeigt die Ergebnisse mit dem, was die Bibliothek schon hat.</li><li>Eine Bestellung wird beim Dienst zur Download-Aufgabe. Der Dienst schreibt die Dateien in das gemeinsame Import-Volume, und der Server importiert sie mit seinem normalen Import – der Dienst berührt die Bibliothek nie.</li></ol><h2 id="einen-dienst-schreiben" tabindex="-1">Einen Dienst schreiben <a class="header-anchor" href="#einen-dienst-schreiben" aria-label="Permalink to &quot;Einen Dienst schreiben&quot;">​</a></h2><ul><li>Setze die Endpunkte der <a href="./reference">Referenz der Schnittstelle</a> für die Schnittstellenversion 1 um.</li><li>Nimm <code>tools/fake-source-service/</code> aus dem Repository als Vorlage: Er spricht jeden Endpunkt und wird von den End-to-End-Tests verwendet.</li><li>Halte die Bedingungen, Ratenbegrenzungen und die robots.txt deiner Quelle ein; melde Ratenbegrenzungen mit <code>rate_limited</code> und <code>retry_after</code>.</li><li>Veröffentliche den Container als einfaches OCI-Image; er läuft im Anthology-Pod auf einem der Ports 8420–8429.</li><li>Wähle die Lizenz deines Dienstes frei. Die Schnittstelle ist die einzige Verbindung zu Anthology.</li></ul><p>Ändert sich die Schnittstelle inkompatibel, erhält sie eine neue Version (<code>/v2</code>); ein Dienst mit anderer Version wird als inkompatibel angezeigt und ausgelassen.</p>',8)])])}const p=n(l,[["render",d]]);export{m as __pageData,p as default};
